 *
 * 7x7x128 int8 convolution engine with hardwired weights.
 *
 * One output pixel = sum over ky,kx,c of w[ky][kx][c] * x[ky][kx][c]
 * (6272 multiply-accumulates). The weights live in a ROM built from logic
 * (src/weights_rom.v, generated by tools/gen_weights.py). The host streams the
 * 6272 activations of one window in ROM order, address = (ky*7 + kx)*128 + c,
 * one signed byte per accepted clock, and reads back a signed 32-bit sum.
 *
 * Pins
 *   ui_in[7:0]   ACT      signed 8-bit activation
 *   uio_in[0]    VALID    ACT is accepted on a rising clk edge while VALID=1
 *   uio_in[1]    START    with VALID: this activation is element 0 of a new window
 *   uio_in[3:2]  BYTE_SEL which byte of the 32-bit result drives uo_out (0 = LSB)
 *   uio_out[5]   BUSY     a window is in progress or still in the pipeline
 *   uio_out[6]   ERR      sticky: VALID seen outside a window; cleared by START
 *   uio_out[7]   DONE     result register holds a finished window; cleared by START
 *   uo_out[7:0]  RESULT   byte BYTE_SEL of the signed 32-bit result
 */

`default_nettype none

module tt_um_ejborcherding_conv7x7 (
    input  wire [7:0] ui_in,    // Dedicated inputs
    output wire [7:0] uo_out,   // Dedicated outputs
    input  wire [7:0] uio_in,   // IOs: Input path
    output wire [7:0] uio_out,  // IOs: Output path
    output wire [7:0] uio_oe,   // IOs: Enable path (active high: 0=input, 1=output)
    input  wire       ena,      // always 1 when the design is powered, so you can ignore it
    input  wire       clk,      // clock
    input  wire       rst_n     // reset_n - low to reset
);

  // N = 7 * 7 * 128 = 6272 weights per window
  localparam integer AW     = 13;           // address bits
  localparam integer ACC_W  = 28;           // |sum| <= 6272 * 16384 < 2^27
  localparam [AW-1:0] LAST_ADDR = 13'd6271;  // N - 1

  // ---------------------------------------------------------------- inputs
  wire       in_valid = uio_in[0];
  wire       in_start = uio_in[1];
  wire [1:0] byte_sel = uio_in[3:2];

  // ------------------------------------------------- stage 0: address + ROM
  reg  [AW-1:0] idx;       // next element index inside the current window
  reg           in_win;    // currently inside a window

  wire          accept   = in_valid & (in_start | in_win);
  wire [AW-1:0] cur_addr = in_start ? {AW{1'b0}} : idx;
  wire          cur_last = (cur_addr == LAST_ADDR);

  wire [7:0] rom_w;
  conv_weights weights_rom (
      .addr(cur_addr),
      .w   (rom_w)
  );

  // ------------------------------------------- stage 1: registered operands
  reg              s1_valid, s1_first, s1_last;
  reg signed [7:0] s1_w, s1_x;

  // ------------------------------------------------- stage 2: accumulate
  reg signed [ACC_W-1:0] acc;
  reg signed [ACC_W-1:0] result;
  reg                    done, err;

  wire signed [15:0]      prod     = s1_w * s1_x;
  wire signed [ACC_W-1:0] acc_base = s1_first ? {ACC_W{1'b0}} : acc;
  wire signed [ACC_W-1:0] acc_next = acc_base + {{(ACC_W - 16){prod[15]}}, prod};

  always @(posedge clk) begin
    if (!rst_n) begin
      idx      <= {AW{1'b0}};
      in_win   <= 1'b0;
      s1_valid <= 1'b0;
      s1_first <= 1'b0;
      s1_last  <= 1'b0;
      s1_w     <= 8'sd0;
      s1_x     <= 8'sd0;
      acc      <= {ACC_W{1'b0}};
      result   <= {ACC_W{1'b0}};
      done     <= 1'b0;
      err      <= 1'b0;
    end else begin
      // stage 0 -> stage 1
      s1_valid <= accept;
      if (accept) begin
        s1_w     <= rom_w;
        s1_x     <= ui_in;
        s1_first <= in_start;
        s1_last  <= cur_last;
        idx      <= cur_addr + 1'b1;
        in_win   <= ~cur_last;
      end

      // framing flags (START clears; a completing window below wins the same cycle)
      if (in_valid & in_start) begin
        done <= 1'b0;
        err  <= 1'b0;
      end else if (in_valid & ~in_win) begin
        err <= 1'b1;
      end

      // stage 1 -> stage 2
      if (s1_valid) begin
        acc <= acc_next;
        if (s1_last) begin
          result <= acc_next;
          done   <= 1'b1;
        end
      end
    end
  end

  // ---------------------------------------------------------------- outputs
  wire [31:0] result32 = {{(32 - ACC_W){result[ACC_W-1]}}, result};

  reg [7:0] out_byte;
  always @(*) begin
    case (byte_sel)
      2'd0:    out_byte = result32[7:0];
      2'd1:    out_byte = result32[15:8];
      2'd2:    out_byte = result32[23:16];
      default: out_byte = result32[31:24];
    endcase
  end

  assign uo_out  = out_byte;
  assign uio_out = {done, err, (in_win | s1_valid), 5'b0};
  assign uio_oe  = 8'b1110_0000;

  // List all unused inputs to prevent warnings
  wire _unused = &{ena, uio_in[7:4], 1'b0};

endmodule
